#!/bin/zsh
# Regenerates the README screenshots and GIF on a dedicated simulator with demo data.
#
#   scripts/readme-media.sh [path/to/workouts.json]
#
# Without an argument the demo data is generated by scripts/demo-workouts.py.
# Needs Xcode and ffmpeg (brew install ffmpeg). Output: WorkoutTracker/GithubAssets/.
set -euo pipefail

export DEVELOPER_DIR=${DEVELOPER_DIR:-/Applications/Xcode.app/Contents/Developer}
ROOT=${0:A:h:h}
OUT="$ROOT/WorkoutTracker/GithubAssets"
WORK=$(mktemp -d)
BUNDLE=com.jones.WorkoutTracker
SIM_NAME="WorkoutTracker README"
DEVICE_TYPE="com.apple.CoreSimulator.SimDeviceType.iPhone-17-Pro"

cleanup() { [[ -n ${REC_PID:-} ]] && kill -INT $REC_PID 2>/dev/null || true; }
trap cleanup EXIT

# 1. A dedicated simulator, so no personal simulator data is touched
UDID=$(xcrun simctl list devices -j | python3 -c "
import json,sys
for devs in json.load(sys.stdin)['devices'].values():
    for d in devs:
        if d['name'] == '$SIM_NAME' and d['isAvailable']: print(d['udid']); sys.exit()")
if [[ -z $UDID ]]; then
  RUNTIME=$(xcrun simctl list runtimes -j | python3 -c "
import json,sys; print([r['identifier'] for r in json.load(sys.stdin)['runtimes'] if r['platform']=='iOS' and r['isAvailable']][-1])")
  UDID=$(xcrun simctl create "$SIM_NAME" "$DEVICE_TYPE" "$RUNTIME")
fi
xcrun simctl bootstatus "$UDID" -b >/dev/null
xcrun simctl ui "$UDID" appearance dark
xcrun simctl status_bar "$UDID" override --time "09:41" --batteryState charged --batteryLevel 100 \
  --cellularMode active --cellularBars 4 --wifiBars 3 --operatorName ""

# 2. Build the app and UI tests, install, seed demo data
xcodebuild build-for-testing -project "$ROOT/WorkoutTracker.xcodeproj" -scheme WorkoutTracker \
  -destination "id=$UDID" -derivedDataPath "$WORK/dd" -quiet
APP=$(find "$WORK/dd/Build/Products" -maxdepth 2 -name WorkoutTracker.app | head -1)
xcrun simctl terminate "$UDID" $BUNDLE 2>/dev/null || true
xcrun simctl install "$UDID" "$APP"

DATA=${1:-$WORK/workouts.json}
[[ -n ${1:-} ]] || python3 "$ROOT/scripts/demo-workouts.py" "$DATA"
CONTAINER=$(xcrun simctl get_app_container "$UDID" $BUNDLE data)
mkdir -p "$CONTAINER/Library/Application Support"
cp "$DATA" "$CONTAINER/Library/Application Support/workouts.json"
xcrun simctl spawn "$UDID" defaults write $BUNDLE hasSeenHealthOnboarding -bool YES
xcrun simctl spawn "$UDID" defaults write $BUNDLE userName -string "Johannes"
xcrun simctl spawn "$UDID" defaults write $BUNDLE weeklyGoal -int 4

# 3. Run the tour while recording the screen (no parallel testing: it would run on a clone)
xcrun simctl io "$UDID" recordVideo --codec h264 --force "$WORK/tour.mov" &
REC_PID=$!
REC_START=$(python3 -c "import time; print(time.time())")
sleep 2
TEST_RUNNER_README_SCREENSHOT_DIR="$OUT" xcodebuild test-without-building \
  -project "$ROOT/WorkoutTracker.xcodeproj" -scheme WorkoutTracker -destination "id=$UDID" \
  -derivedDataPath "$WORK/dd" -only-testing:WorkoutTrackerUITests/ReadmeScreenshots \
  -parallel-testing-enabled NO -quiet
kill -INT $REC_PID; wait $REC_PID 2>/dev/null || true; REC_PID=
for png in "$OUT"/0*.png; do sips -Z 1300 "$png" >/dev/null; done   # half size is plenty for a README

# 4. GIF of just the tour (the test writes start/end times): 1.5x speed, 10 fps, 300 px wide
FROM=$(python3 -c "print(max(0, $(cat "$OUT/.tour-start") - $REC_START))")
TO=$(python3 -c "print($(cat "$OUT/.tour-end") - $REC_START + 0.5)")
rm -f "$OUT/.tour-start" "$OUT/.tour-end"
ffmpeg -loglevel error -y -ss "$FROM" -to "$TO" -i "$WORK/tour.mov" \
  -vf "setpts=PTS/1.5,fps=10,scale=300:-1:flags=lanczos,split[a][b];[a]palettegen=max_colors=96:stats_mode=diff[p];[b][p]paletteuse=dither=bayer:bayer_scale=4:diff_mode=rectangle" \
  "$OUT/tour.gif"

xcrun simctl status_bar "$UDID" clear
echo "Wrote screenshots and tour.gif to $OUT"
